var(--acid)}.bullet-icon{font-size:24px;color:var(--acid);text-shadow:0 0 12px #d4ff48;line-height:1}.pickup-prompt{inset:auto auto 90px 50%;transform:translateX(-50%);z-index:6;width:max-content;height:auto;padding:8px 13px;background:#161319df;border:1px solid #d4ff4880;color:var(--acid);font:10px 'DM Mono',monospace;letter-spacing:.1em;box-shadow:0 4px 20px #0009;opacity:0;transition:opacity .15s}.pickup-prompt.visible{opacity:1}.pickup-prompt kbd{font:inherit;border:1px solid #d4ff48;padding:2px 5px;margin-right:8px}.damage-flash{z-index:7;background:#ff1c2450;opacity:0;transition:opacity .22s}.damage-flash.hit{opacity:1}.toast{inset:22% auto auto 50%;transform:translateX(-50%);width:max-content;height:max-content;z-index:8;font:10px 'DM Mono',monospace;letter-spacing:.14em;color:var(--acid);text-shadow:0 1px 5px #000;opacity:0;transition:opacity .2s}.toast.show{opacity:1}.overlay{z-index:10;display:flex;align-items:center;justify-content:center;background:#100d12a6;backdrop-filter:blur(3px);pointer-events:auto}.overlay.hidden{display:none}.overlay-card{position:relative;width:min(440px,80%);padding:30px 34px 25px;background:#17141beF;border:1px solid #5b5059;box-shadow:0 20px 70px #000a}.overlay-card:before{content:'';position:absolute;top:-1px;left:-1px;width:48px;height:3px;background:var(--acid)}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.17em;color:#aaa2ac}.eyebrow span{margin-right:6px}.overlay-card h1{font-size:clamp(48px,8vw,82px);font-weight:900;letter-spacing:-.025em;line-height:.75;margin:21px 0 19px;text-shadow:4px 4px 0 #343039}.overlay-card h1 em{font-style:normal;color:var(--acid)}.overlay-card p{color:#bbb3bd;font-size:15px;line-height:1.35;margin:0 0 22px}.overlay-card p b{color:#f2ecf2;font-weight:600}.start-button{height:43px;width:100%;display:flex;align-items:center;justify-content:space-between;padding:0 14px;border:0;background:var(--acid);color:#171515;font-size:14px;font-weight:800;letter-spacing:.12em;cursor:pointer;transition